import { randomBytes } from "node:crypto";

import { db } from "./db";
import { sendEmail } from "./email";

export async function requestPasswordReset(email: string): Promise<{ status: 202 }> {
  const user = await db.one<{ id: string } | null>("SELECT id FROM users WHERE email = $1", [email]);
  if (user !== null) {
    const token = randomBytes(32).toString("hex");
    await db.query(
      "INSERT INTO password_resets (user_id, token, expires_at) VALUES ($1, $2, now() + interval '1 hour')",
      [user.id, token],
    );
    await sendEmail(email, "Reset your password", `Your reset token: ${token}`);
  }
  return { status: 202 };
}
